entries[451234] = { ["name"] = "Leergespenst", ["text"] = "Verwandelt Euren Schattengeist oder Geistbeuger in ein Leergespenst.\n\nLeergespenst\nBeschwört für 15 Sek. ein Leergespenst, das aus der Distanz 'Leerenschinden' einsetzt. 'Leerenschinden' fügt Gegnern mit hoher Gesundheit Bonusschaden zu, bis maximal 50%, wenn sie bei voller Gesundheit sind. [ Schatten : Erzeugt mit jedem Angriff des Leergespensts 2 Wahnsinn. /\n\nDisziplin, Heilig\nErzeugt mit jedem Angriff des Leergespensts 0.5% Mana. ]" }
