entries[451367] = { ["name"] = "Tröstlicher Kerzenschein", ["text"] = "Sofort\nEure Zauber haben eine Chance, das Wachs zu verzaubern, um für 15 Sek. eine lodernde Kerze zu erzeugen, die Eure Vielseitigkeit um 122 und, während Ihr in ihrem Licht bleibt, weiter um 32 erhöht." }
