entries[451369] = { ["name"] = "Ermächtigende Dunkelheit", ["text"] = "Sofort\nEure Fähigkeiten haben eine Chance, die Dunkelheit zu Euch zu rufen, wodurch sich Eure Hauptwert um 19 erhöht, bis zu ( 19 * 5).\n\nBei Erreichen voller Kraft wird die Dunkelheit entfesselt und verursacht ( 1 * 1789 * 15 / 3) Schattenschaden, die zwischen Gegnern in der Nähe im Verlauf von 15 Sek. aufgeteilt werden, bevor sie wieder in das Fragment verblasst." }
entries[451372] = { ["name"] = "Stabilisieren!", ["text"] = "Kanalisiert (Wirken in 5 sek.) 20 sek. Abklingzeit\nStabilisiert Euch!\n\nHalten, um gewonnene Stabilität zu erhöhen. Trefft den idealen Punkt für einen vorübergehenden Temposchub!\n\n1: Erhöht Stabilität um 20.\n2: Erhöht Stabilität um 40.\n3: Idealer Punkt! Setzt Stabilität auf 100 und gewährt die Stärkung 'Perfekte Balance!'.\n4: Erhöht Stabilität um 60." }
