entries[451607] = { ["name"] = "Lähmende Wellen", ["text"] = "Unbegrenzte Reichweite\nSofort\nRollende Wellen aus Gift fügen Spielercharakteren auf ihrem Weg 11512630 Naturschaden zu, stoßen diese weg und belegen sie mit ' Lähmendes Toxin '." }
entries[451608] = { ["name"] = "Fließende Schritte", ["text"] = "Wirken in 2 sek.\nDer Körper des Zaubernden fließt wie Wasser. Erlaubt ihm, 5 Sek. lang alle Angriffe und Zauber zu vermeiden." }
entries[451609] = { ["name"] = "Netzbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nStrangspinnerin Takazj verschießt explodierende Netze auf Spielercharaktere, die allen Spielercharakteren innerhalb von 10 Metern 20 Naturschaden zufügen.\n\nWenn sich mehr als ein Spielercharakter im Bereich befindet, werden die Spielercharaktere mit ' Bindende Netze ' aneinander gefesselt, was die Bewegungsgeschwindigkeit um 20 % verringert.\n\nWenn sich gefesselte Spielercharaktere mehr als 30 Meter voneinander entfernen oder Anub'arash durch das Netz stürmt, wird es zerstört und entfernt ' Bindende Netze '." }
entries[451610] = { ["name"] = "Netzbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nTakazj verschießt klebrige Gespinstknoten in der Kammer, die die Bewegungsgeschwindigkeit von Spielercharakteren um 20% verringern und ihnen alle 1 Sek. 345379 körperlichen Schaden zufügen, während diese sich im Effektbereich befinden.\n\nDer Knoten in der Mitte bricht bei Berührung aus, was Spielercharakteren innerhalb von 10 Metern 1732248 Naturschaden zufügt und ' Bindende Netze ' einsetzt, um zwei Spielercharaktere mit aneinanderzubinden.\n\nWenn Anub'arash durch Stränge von 'Bindende Netze' stürmt, wird er 'Umschlungen'." }
entries[451611] = { ["name"] = "Netzbombenziel", ["text"] = "100 Meter Reichweite\nSofort\nTakazj verschießt klebrige Gespinstknoten in der Kammer, die die Bewegungsgeschwindigkeit von Spielercharakteren um 20% verringern und ihnen alle 1 Sek. 345379 körperlichen Schaden zufügen, während diese sich im Effektbereich befinden.\n\nDer Knoten in der Mitte bricht bei Berührung aus, was Spielercharakteren innerhalb von 10 Metern 1732248 Naturschaden zufügt und ' Bindende Netze ' einsetzt, um zwei Spielercharaktere mit aneinanderzubinden.\n\nWenn Anub'arash durch Stränge von 'Bindende Netze' stürmt, wird er 'Umschlungen'." }
