entries[451699] = { ["name"] = "Umarmung der Glutbiene", ["text"] = "Sofort\nEure Zauber und Fähigkeiten haben eine Chance, eine schwebende Feuerpollenkugel in der Nähe zu erschaffen. Wenn Ihr in die Kugel tretet, sammelt Ihr sie auf, was Euren höchsten Sekundärwert 12 Sek. lang um 1045 erhöht. Bis zu 2 Verbündete, die in dieser Zeit in Eure Nähe treten, erhalten 12 Sek. lang 87 eines zufälligen Sekundärwerts." }
