entries[451701] = { ["name"] = "Reaktiver Schaum", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ein Spielercharakter den Schaum berührt, explodiert er und belegt den Spielercharakter mit ' Konzentriertes Toxin '.\n\nDiese Explosion schleudert den Spielercharakter 8 Meter in die Luft und fügt allen Spielercharakteren 1151263 Naturschaden zu und belegt sie mit ' Schäumendes Toxin ' und ' Toxische Reaktion '. Außerdem wird ein Giftklumpen weggeschleudert, der ' Giftige Wellen ' auslöst.\n\n' Toxinnova ' zerstreut explodierten Schaum zu einer Lache aus ' Säure '." }
entries[451702] = { ["name"] = "Schwächlinge loswerden", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nOrta schleudert die für ihn erreichbaren Schwächlinge mit aller Kraft von sich weg." }
entries[451703] = { ["name"] = "Schäumendes Toxin", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsureks instabile Säure brennt sich in das Opfer und fügt ihm 6 Sek. lang alle 1 Sek. 575632 Naturschaden zu.\n\nWenn der Effekt abläuft, explodiert das Toxin, belegt das Opfer mit ' Reaktionstrauma ' und fügt allen Spielercharakteren innerhalb von 15 Metern 1726895 Naturschaden zu." }
