entries[451720] = { ["name"] = "Verdünntes Toxin", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsureks geschwächtes Gift verursacht 6 Sek. lang alle 1 Sek. 5 Naturschaden. Dieser Effekt ist stapelbar.\n\nBei Ablauf fügt das Gift allen Spielercharakteren innerhalb von 4 Metern 20 Naturschaden zu." }
