entries[451734] = { ["name"] = "Schleimige Membran", ["text"] = "Wirken in 2.5 sek.\nDer Zaubernde hüllt sich in Honig, der 20 erlittenen Schaden absorbiert. Der Schleim trieft auf Angreifer, fügt ihnen Naturschaden zu und verlangsamt sie um 1%. Dieser Effekt ist stapelbar." }
