entries[451754] = { ["name"] = "Beorderte Elemente", ["text"] = "Unbegrenzte Reichweite\nSofort\nWährend 'Sturm, Erde und Feuer' sind die Chi-Kosten um 1 verringert und 'Blackout-Tritt' verringert die Abklingzeit betroffener Fähigkeiten um weitere 1 Sek.\n\nDie Aktivierung von 'Sturm, Erde und Feuer' setzt die verbleibende Abklingzeit von 'Tritt der aufgehenden Sonne' zurück und gewährt 2 Chi." }
