entries[451767] = { ["name"] = "Wirbelnder Drachenschlag", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen vernichtenden, wirbelnden Aufwärtsschlag, der allen Gegnern in der Nähe [3 * (161% der Angriffskraft)] Schaden sowie dem ersten getroffenen Ziel zusätzlich (300% der Angriffskraft) Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nKann nur eingesetzt werden, während sich sowohl 'Furorfäuste' als auch 'Tritt der aufgehenden Sonne' in der Abklingzeit befinden." }
entries[451769] = { ["name"] = "Abbitte", ["text"] = "Unbegrenzte Reichweite\nSofort\n'Machtwort: Schild', 'Blitzheilung', 'Erneuerung', 'Machtwort: Glanz' und 'Machtwort: Leben' belegen Euer Ziel für 15 Sek. mit dem Effekt 'Abbitte'.\n\nWenn Ihr Zauberschaden verursacht, werden alle mit 'Abbitte' belegten Ziele um 38% des verursachten Schadens geheilt.\n\nDie Heilung ist außerhalb von Schlachtzügen um 75% erhöht." }
