entries[451936] = { ["name"] = "Grimmwebenkugel", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nEntfesselt eine Kugel, die vor dem Zaubernden rasch ein Gespinst bildet, das Gegnern innerhalb von 4 Metern Entfernung zur Kugel 8 Naturschaden sowie zusätzlich alle 1 Sek. 2 Naturschaden zufügt und ihre Bewegungsgeschwindigkeit 3 Sek. lang um 30 % verringert." }
