entries[451938] = { ["name"] = "Schild des Rächers", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nSchleudert einen heiligen Schild auf den Gegner, der ihm 25 Heiligschaden zufügt, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele." }
entries[451939] = { ["name"] = "Umbralwind", ["text"] = "60 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde entfesselt einen Stoß Umbralwinde. Fügt allen Gegnern 4848899 Schattenschaden zu und stößt sie zurück." }
entries[451940] = { ["name"] = "Azeritwoge", ["text"] = "100 Meter Reichweite\nSofort\nAtmet ein und facht Euer inneres Feuer an. Setzt den Atem frei, um Gegner in einem kegelförmigen Bereich vor Euch zu verbrennen und ihnen [((163.409% der Zaubermacht)) + ((39.4834% der Zaubermacht) * (10 + 0 ))] Feuerschaden zuzufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Sande der Zeit : Erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 2 Sek ]\nBei Ermächtigung wird ein höherer Anteil des Schadens sofort anstatt als regelmäßiger Schaden verursacht.\n\nI: Verursacht sofort [(163.409% der Zaubermacht)] Schaden und [(39.4834% der Zaubermacht) * (10 + 0 )] Schaden im Verlauf von (20 + 0 ) Sek.\n\nII: Verursacht sofort [(163.409% der Zaubermacht) + ((39.4834% der Zaubermacht) * 3)] Schaden und [(39.4834% der Zaubermacht) * (7 + 0 )] Schaden im Verlauf von (14 + 0 ) Sek.\n\nIII: Verursacht sofort [(163.409% der Zaubermacht) + ((39.4834% der Zaubermacht) * 6)] Schaden und [(39.4834% der Zaubermacht) * (4 + 0 )] Schaden im Verlauf von (8 + 0 ) Sek." }
entries[451943] = { ["name"] = "Jadeschnelligkeit", ["text"] = "Sofort\nWindläufer\nSchlägt heftig auf den Boden, um für 30 Sek. einen Jadeweg freizulegen, der Eure Bewegungsgeschwindigkeit innerhalb des Effektbereichs um 20% erhöht. Fügt bis zu 5 vom Jadeweg erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit. Bis zu 5 vom Weg erfasste Gegner\n\nNebelwirker\nSchlägt heftig auf den Boden, um für 30 Sek. einen Jadeweg freizulegen. Fügt bis zu 5 vom Jadeweg erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit.\n\nWährend Ihr innerhalb des Wegs kämpft, haben Eure Fähigkeiten eine Chance von 6%, die Abklingzeit von 'Jadefeuerstampfen' abzuschließen." }
