entries[451968] = { ["name"] = "Schadensumleitung", ["text"] = "100 Meter Reichweite\nSofort\nNebelwirker ( Nebelwirkermönch )\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 25% des geheilten Werts als Naturschaden zufügt.\n\nBraumeister, Windläufer\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Nebelwirker ( Nebelwirkermönch )\n\nEntzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen.\n\nBraumeister, Windläufer\n\nEntzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Nebelwirker ( Nebelwirkermönch )\n\nErzeugt [(120% der Zaubermacht) + 30] Chi.\n\nBraumeister, Windläufer\n\nErzeugt [(120% der Zaubermacht) + 30] Chi. ]" }
