entries[452146] = { ["name"] = "Eiersack", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeiten haben eine Chance, den Kokon zu bewegen, der ein Ei freigibt, das Eure Hauptwert um 15 erhöht. Jedes Ei schlüpft nach 1 Min. Die neue Brut greift Euer nächstes Ziel an und fügt ihm im Verlauf von 8 Sek. ( 1 * 80 * 8) Naturschaden zu." }
