entries[452402] = { ["name"] = "Dämonenwoge", ["text"] = "Verwüstung\nDer Zauber 'Metamorphose' lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen.\n\nWährend die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nRachsucht\nDer Zauber 'Metamorphose' ermächtigt 'Seelenspalter' und 'Seelenbombe' stark.\n\nWährend die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[452403] = { ["name"] = "Welle der Entkräftung", ["text"] = "'Chaosnova' verlangsamt Gegner um 60% und verringert das Angriffs- und Zaubertempo 5 Sek. lang um 15%, nachdem ihre Betäubung abgeklungen ist." }
entries[452404] = { ["name"] = "Streben nach Wut", ["text"] = "Bewegungsgeschwindigkeit um 1% pro 10 Jähzorn erhöht." }
entries[452405] = { ["name"] = "Fokussierter Hass", ["text"] = "Eure 'Dämonenwoge' verursacht 50% mehr Schaden, wenn sie ein einzelnes Ziel trifft.\n\nJedes weitere Ziel reduziert diesen Bonus um 10%." }
entries[452406] = { ["name"] = "Brennende Schmerzen", ["text"] = "5% sämtlichen erlittenen Schadens außer Feuerschaden wird stattdessen als Feuerschaden im Verlauf von 6 Sek. erlitten.\n\nDer erlittene Feuerschaden wird um 10% reduziert." }
entries[452407] = { ["name"] = "Verbesserter Seelenreißer", ["text"] = "Durch 'Seelenreißer' gewährter Lebensraub wurde um 2% und zusätzlich um 2% erhöht, während 'Metamorphose' aktiv ist." }
entries[452408] = { ["name"] = "Brennende Klingen", ["text"] = "Verwüstung\nEure Klingen brennen mit Teufelsenergie, wodurch Eure 'Chaosstoß', 'Gleve werfen' und automatischen Angriffe zusätzlich 50% Schaden als Feuer über 6 Sek. zufügen.\n\nRachsucht\nEure Klingen brennen mit Teufelsenergie, wodurch Eure 'Seelenspalter', 'Gleve werfen' und automatischen Angriffe zusätzlich 40% Schaden als Feuer über 6 Sek. zufügen." }
entries[452409] = { ["name"] = "Gewaltsame Verwandlung", ["text"] = "Rachsucht\nWenn Ihr 'Metamorphose' aktiviert, werden die Abklingzeiten Eurer Zauber 'Zeichen der Flamme' und 'Dämonische Verwüstung' sofort zurückgesetzt.\n\nVerwüstung\nWenn Ihr 'Metamorphose' aktiviert, werden die Abklingzeiten Eurer Zauber 'Zeichen der Flamme' und 'Feuerbrandaura' sofort zurückgesetzt." }
entries[452410] = { ["name"] = "Andauernde Folter", ["text"] = "Verwüstung\nDie Effekte Eurer Dämonenform bestehen in abgeschwächter Form auch außerhalb davon fort und erhöhen den Schaden von 'Chaosstoß' und 'Klingentanz' um 15% und Euer Tempo um 5%.\n\nRachsucht\nDie Effekte Eurer Dämonenform bestehen in abgeschwächter Form auch außerhalb davon fort und erhöhen die maximale Gesundheit um 5% und die Rüstung um 20%." }
entries[452411] = { ["name"] = "Freigelassener Jähzorn", ["text"] = "Erhöht den maximalen Jähzorn um 50." }
entries[452412] = { ["name"] = "Lehren des Leids", ["text"] = "'Zeichen der Flamme' kann 'Lehren des Leids' auf Euch anwenden, was Eure Meisterschaft um (8 * [Quellwert] as)% erhöht und 6 Sek. lang alle 2 Sek. 5 Jähzorn gewährt.", ["unresolvedValues"] = true }
entries[452413] = { ["name"] = "Flammengebunden", ["text"] = "'Feuerbrandaura' hat einen um 2 Meter erhöhten Radius und einen um 50% erhöhten kritischen Schadensbonus." }
entries[452414] = { ["name"] = "Aufsteigendes Monster", ["text"] = "Beweglichkeit ohne Dämonenform um 8% erhöht." }
entries[452415] = { ["name"] = "Dämonische Intensität", ["text"] = "Verwüstung\nDie Aktivierung von 'Metamorphose' verstärkt 'Augenstrahl', 'Feuerbrandaura' und 'Zeichen der Flamme' stark.\n\nDer Schaden durch 'Dämonenwoge' wird für jede vorherige Aktivierung während Eurer Dämonenform um 10 % erhöht.\n\nRachsucht\nDie Aktivierung von 'Metamorphose' verstärkt 'Dämonische Verwüstung', 'Feuerbrandaura' und 'Zeichen der Flamme' stark.\n\nDer Schaden durch 'Dämonenwoge' wird für jede vorherige Aktivierung während Eurer Dämonenform um 10 % erhöht." }
entries[452416] = { ["name"] = "Dämonenwoge", ["text"] = "Sofort\nDer Zauber 'Metamorphose' [ Verwüstung : lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen /\n\nRachsucht\nermächtigt 'Seelenspalter' und 'Seelenbombe' stark ]\nWährend die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[452417] = { ["name"] = "Skorpionexplosion" }
entries[452418] = { ["name"] = "Rüpelschrei", ["text"] = "100 Meter Reichweite\nSofort\nDurstige Gäste schmettern auf ihren Tisch, fügen damit allen Spielercharaktere alle 2 Sek. 484890 körperlichen Schaden zu und verringern deren Tempo um 25%.\n\nWenn ihnen ein Becher Glutbräu gebracht wird, hört ihre Raserei auf." }
entries[452419] = { ["name"] = "Gedankenschlag", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nFügt einem Gegner 0 Schattenschaden zu." }
entries[452421] = { ["name"] = "Sprengstoff der Irdenen", ["text"] = "Sofort\nTrägt Sprengstoff der Irdenen." }
entries[452422] = { ["name"] = "Notizen studieren", ["text"] = "Wirken in 2 sek.\nStudiert Eure Notizen, um einen neuen Ingenieurskunstbauplan auszuwählen, den Ihr erlernen wollt.\n\nJe weiter Ihr Euch in der Ingenieurskunst spezialisiert, desto mehr Baupläne stehen dafür zur Verfügung." }
entries[452423] = { ["name"] = "Sprengkörper werfen", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nVerursacht in einem Gebiet massiven körperlichen Schaden." }
