entries[452436] = { ["name"] = "Seelenvernichtung", ["text"] = "30 Jähzorn Nahkampfreichweite\nSofort\nSchlägt brutal auf bis zu 5 Gegner vor Euch ein, fügt ihnen (154% der Angriffskraft) körperlichen Schaden zu und heilt Euch um (50% der Angriffskraft) Gesundheit.\n\nVerbraucht bis zu 2 verfügbare Seelenfragmente [ Seelenspalter : und heilt Euch pro verbrauchtem Seelenfragment zusätzlich um (50% der Angriffskraft) Gesundheit ]." }
entries[452437] = { ["name"] = "Geistexplosion", ["text"] = "40 Jähzorn\nSofort\nZehrt bis zu 5 verfügbare Seelenfragmente auf, explodiert dann, um Gegnern in der Nähe (36.5% der Angriffskraft) Feuerschaden pro aufgezehrtem Fragment zuzufügen, und belegt sie 6 Sek. lang mit 'Gebrechlichkeit', wodurch Ihr um 8% des Schadens geheilt werdet, den Ihr Euren Gegnern zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[452438] = { ["name"] = "Arkanbeschusssalve", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nDer Zaubernde verschießt eine Salve arkaner Geschosse auf Spielercharaktere innerhalb von 30 Metern, die Arkanschaden verursacht." }
entries[452440] = { ["name"] = "Entsetzliches Heulen", ["text"] = "40 Meter Reichweite\nSofort\nDas Heulen von 'Schrecken der Schmiede' fügt Spielercharakteren 15 Schallschaden zu und versetzt sie für 3 Sek. in Furcht." }
