entries[452443] = { ["name"] = "Dämonenwoge", ["text"] = "Sofort\nDer Zauber 'Metamorphose' [ Verwüstung : lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen /\n\nRachsucht\nermächtigt 'Seelenspalter' und 'Seelenbombe' stark ]\nWährend die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[452444] = { ["name"] = "Verstärkung heranführen", ["text"] = "Unbegrenzte Reichweite\nSofort\nBringt weitere Mitglieder des Ordens der Nacht hervor, die den Zaubernden 2 Sek. lang im Kampf unterstützen. Diese beginnen mit verringerter Gesundheit, wobei ' Verstärkung heranführen ' die fehlende Gesundheit mit der Zeit heilt.\n\nDiese Einheiten sind mit ' Schnellbeschwörung ' belegt.\n\nSchnellbeschwörung\nBeeinträchtigt durch Schnellbeschwörung, reduziert verursachten Schaden um 80% und Gesundheit um 70%." }
