entries[452532] = { ["name"] = "Instabile Substanz", ["text"] = "Sofort\nDer Wesir hat Euch eine Tasche mit nicht beschrifteten experimentellen Tränken geschenkt, die Ihr freizügig gegen Eure Gegner in Azj-Kahet einsetzen könnt." }
entries[452533] = { ["name"] = "Magischer Schabernack", ["text"] = "Wirken in 1 sek. 2 std. Abklingzeit\nSetzt eine Maske auf, die Euer Aussehen so verändert, dass Ihr einem anderen Bewohner Azeroths ähnelt.\n\nHält je nach Qualität des Freudenzaubers 20-60 Min. lang an." }
