entries[452535] = { ["name"] = "Sphäre des Astraleums", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde nutzt arkane Magie, um eine Kugel zu erschaffen, die sich 20 Sek. lang auf ihn zubewegt." }
entries[452536] = { ["name"] = "Hand des Schicksals", ["text"] = "Wirft immer, wenn ein Finishing-Move 5 oder mehr Combopunkte verbraucht, eine schicksalsgebundene Münze. Kopf erhöht den Schaden Eurer Angriffe 15 Sek. lang, oder bis Ihr Zahl werft, um 10%. Zahl fügt Eurem Ziel (210% der Angriffskraft) kosmischen Schaden zu.\n\nImmer wenn der Wurf das gleiche Ergebnis wie der vorherige Wurf hat, wird bei Kopf der Schaden um zusätzliche 2% und bei Zahl der Schaden um 10% erhöht." }
entries[452537] = { ["name"] = "Leerenschlag", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nFügt dem Ziel 8 Schattenschaden zu." }
