entries[452567] = { ["name"] = "Unrat hochwürgen", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nEidfresser würgt und spuckt die Überreste seiner vorherigen Mahlzeiten auf den Spielercharakter, was diesem Naturschaden zufügt." }
entries[452571] = { ["name"] = "Update Phase Shift Zone Aura" }
entries[452578] = { ["name"] = "Verstärkung heranführen", ["text"] = "Unbegrenzte Reichweite\nSofort\nBringt weitere Mitglieder des Ordens der Nacht hervor, die den Zaubernden 2 Sek. lang im Kampf unterstützen. Diese beginnen mit verringerter Gesundheit, wobei ' Verstärkung heranführen ' die fehlende Gesundheit mit der Zeit heilt.\n\nDiese Einheiten sind mit ' Schnellbeschwörung ' belegt.\n\nSchnellbeschwörung\nBeeinträchtigt durch Schnellbeschwörung, reduziert verursachten Schaden um 80% und Gesundheit um 70%." }
